CREATE TABLE public.loan_term_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),loan_id uuid NOT NULL REFERENCES public.loans(id),frequency text NOT NULL,installment_count integer NOT NULL,first_due date NOT NULL,paid_at_revision numeric(16,2) NOT NULL,schedule jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.loan_term_revisions TO authenticated; GRANT ALL ON public.loan_term_revisions TO service_role;
ALTER TABLE public.loan_term_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY loan_revisions_read ON public.loan_term_revisions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.loans WHERE id=loan_id));
CREATE FUNCTION public.adjust_loan_terms(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.loans;paid numeric;remaining numeric;n integer:=(p->>'installments')::integer;f text:=p->>'frequency';firstdate date:=(p->>'first_due')::date;due date;base numeric;k integer;plan jsonb:='[]';rid uuid;today date:=(now() AT TIME ZONE 'Asia/Colombo')::date; BEGIN SELECT * INTO l FROM public.loans WHERE id=(p->>'loan_id')::uuid FOR UPDATE; IF NOT FOUND OR NOT public.staff_can('Manage loan terms',l.branch_id) THEN RAISE EXCEPTION 'Loan term management permission required'; END IF; IF n IS NULL OR n<1 OR n>120 OR firstdate IS NULL OR firstdate<today OR f IS NULL OR f NOT IN('Monthly','Every 2 weeks','Weekly') THEN RAISE EXCEPTION 'Choose 1–120 installments, a valid frequency and a due date from today'; END IF; SELECT coalesce(sum(amount),0) INTO paid FROM public.loan_payments WHERE loan_id=l.id;remaining:=l.amount-paid;IF remaining<=0 THEN RAISE EXCEPTION 'Closed loans cannot be rescheduled';END IF;IF paid>0 THEN plan:=jsonb_build_array(jsonb_build_object('installment_no',0,'due_date',today,'amount',paid));END IF;base:=floor(remaining*100/n)/100;IF base<=0 THEN RAISE EXCEPTION 'Too many installments for the remaining balance';END IF; FOR k IN 1..n LOOP IF f='Monthly' THEN due:=(date_trunc('month',firstdate)+(k-1)*interval '1 month')::date;due:=due+least(extract(day from firstdate)::int,extract(day from (due+interval '1 month - 1 day'))::int)-1;ELSE due:=firstdate+(k-1)*CASE WHEN f='Weekly' THEN 7 ELSE 14 END;END IF;plan:=plan||jsonb_build_array(jsonb_build_object('installment_no',k,'due_date',due,'amount',CASE WHEN k=n THEN remaining-base*(n-1) ELSE base END));END LOOP;INSERT INTO public.loan_term_revisions(loan_id,frequency,installment_count,first_due,paid_at_revision,schedule,created_by) VALUES(l.id,f,n,firstdate,paid,plan,auth.uid()) RETURNING id INTO rid;INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Staff'),l.branch_id,'Loans','Rescheduled','Changed terms for '||l.loan_no||' to '||n||' installments, '||f||', starting '||firstdate,rid::text);RETURN rid;END $$;
REVOKE ALL ON FUNCTION public.adjust_loan_terms(jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.adjust_loan_terms(jsonb) TO authenticated;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.save_staff_role(jsonb)'::regprocedure) INTO d;d:=replace(d,'''Manage expenses'']','''Manage expenses'',''Manage loan terms'']');EXECUTE d;END $$;